            for(auto const& h:a.at("hands")){unsigned side=h.at("side")=="right"?1:0;auto& q=p.poses[side];q.side=side;q.wrist_in_object=workbench::pose(h.at("wrist_in_object"));q.mapped=h.at("retargeted");q.fully_tracked=h.at("fully_tracked");q.source_time=h.at("source_time_ns");q.authored_default=h.value("authored_default",false);q.part_delta_known=h.value("part_delta_known",false);if(q.part_delta_known)q.part_delta=workbench::pose(h.at("part_delta_in_object"));q.data_source=h.value("hand_data_source",0u);q.starter_angle=h.value("starter_angle_radians",0.);q.charging_distance=h.value("charging_distance_metres",0.);if(!std::isfinite(q.starter_angle)||q.starter_angle<0||q.starter_angle>1.571||!std::isfinite(q.charging_distance)||q.charging_distance<0||q.charging_distance>.231||q.data_source>2)throw std::runtime_error("Invalid captured component state");if(h.at("local_fingers_xyzw").size()!=15||h.at("raw_joints_in_object").size()!=26)throw std::runtime_error("Invalid pose size");for(unsigned k=0;k<15;++k){q.local[k]=quaternion(h.at("local_fingers_xyzw").at(k));p.finger_degrees[side][k]=vector(h.at("finger_correction_degrees").at(k));if(length(p.finger_degrees[side][k])>180)throw std::runtime_error("Invalid finger correction");}p.wrist_offset[side]=vector(h.at("wrist_offset_metres"));p.wrist_degrees[side]=vector(h.at("wrist_correction_degrees"));if(length(p.wrist_degrees[side])>180)throw std::runtime_error("Invalid wrist rotation");if(length(p.wrist_offset[side])>.3)throw std::runtime_error("Invalid wrist offset");for(unsigned k=0;k<26;++k){auto const& raw=h.at("raw_joints_in_object").at(k);q.raw_in_object[k]={workbench::pose(raw.at("pose")),raw.at("radius_metres"),raw.at("flags")};}p.known[side]=true;}
