                if(hover_[id]<0){double score=1e6;for(unsigned part=0;part<parts_.size();++part){if(ammo_editing()&&part!=2)continue;if(generic_model()&&!generic_info_.at("parts")[part].value("editor_visible",true))continue;double hit=ray_volume_score(ray,displayed_volume(part,shown_),shown_.object);if(hit>=0&&hit<score){score=hit;part_hover_[id]=int(part);}}}
                if(press&&hover_[id]<0){if(!testing_&&inspector_open_&&inspector_tab_==2&&hand_mesh_known_[edit_side_]){auto joints=fk(hands_[edit_side_].rig,hand_local_[edit_side_]);int chosen=-1;double best=1e6;for(unsigned j=0;j<16;++j){Volume point{};point.radius=j?.012:.018;point.local.position=compose(hand_pose_[edit_side_],joints[j]).position;double score=ray_volume_score(ray,point,P{});if(score>=0&&score<best){best=score;chosen=int(j);}}if(chosen>=0){if(chosen==0)hand_tool_=1;else{hand_tool_=0;joint_=unsigned(chosen-1);}continue;}}if(!testing_&&inspector_open_&&inspector_tab_==1&&rotation_drag_.begin(id,ray,compose(shown_.object,displayed_volume(part_,shown_).local),selected().volume.local.orientation,part_)){grab_={};continue;}if(part_hover_[id]>=0){select_part(unsigned(part_hover_[id]));continue;}}
