        if(!testing_&&!paused_){std::array<P,2> wrists{};std::array<bool,2> known{};for(unsigned side=0;side<2;++side)known[side]=wrist(side,grab_source_[side],wrists[side]);if(grab_.owner>=0&&!known[grab_.owner]){grab_={};message_="追踪中断，枪已固定，请重新拿起";}follow_at(grab_,wrists,known,live_.object);}
        
        shown_=paused_&&frozen_known_?frozen_:live_;
        build_ui();if(testing_)practice_input();else update_input();sync_ammo_stage();if(capture_due_&&live_.time_ns>=capture_due_){capture_due_=0;try{capture_pose();}catch(std::exception const& e){message_=e.what();}}
